function screenBearing(angle){return Math.atan2((Math.cos(angle)+Math.sin(angle))*.51,Math.cos(angle)-Math.sin(angle));}
function bearingIndex(angle){return (Math.round(screenBearing(angle)/(Math.PI/4))+8)%8;}
function gunGeometry171(o){var angle=o.aim===undefined?-Math.PI/2:o.aim,index=bearingIndex(angle),g=combatGuns171[index],scale=o.type?.15:.105,desired=screenBearing(angle),rotation=desired-Math.atan2(g[7]-g[5],g[6]-g[4]),r=(o.recoil||0)/.18*2,height=o.type?27:14,len=Math.hypot(g[6]-g[4],g[7]-g[5])*scale-r;return{index:index,rotation:rotation,scale:scale,height:height,recoil:r,x:Math.cos(desired)*len,y:Math.sin(desired)*len-height};}
// Directional weapons use one model for rendering and the projectile origin.
function isTracked(o){return o.kind===1||o.kind===9;}
function turnAngle(from,to,step){var delta=Math.atan2(Math.sin(to-from),Math.cos(to-from));return from+Math.max(-step,Math.min(step,delta));}
function weaponMount(o){if(o.type==='missileturret'){var a=screenBearing(o.aim===undefined?-Math.PI/2:o.aim),l=22-(o.recoil||0)/.18*2;return{x:Math.cos(a)*l,y:Math.sin(a)*l-26,height:26};}if(isTracked(o)||['gun','cannonturret','missileturret'].includes(o.type))return gunGeometry171(o);var angle=o.aim===undefined?-Math.PI/2:o.aim,h=o.kind===7?40:o.type?(o.type==='hq'?30:o.type==='tesla'?35:25):isTracked(o)?13:17,l=(o.type?22:isTracked(o)?22:13)-(o.recoil||0)/.18*3;return{x:Math.cos(angle)*l-Math.sin(angle)*l,y:(Math.cos(angle)*l+Math.sin(angle)*l)*.51-h,height:h};}
function updateMotion(scene,dt){var units=[].concat(scene.troops||[],scene.guards||[],scene.enemies||[],scene.defenders||[]),all=scene.buildings.concat(units);all.forEach(function(o){o.recoil=Math.max(0,(o.recoil||0)-dt);var dx=o.x-(o.lastX===undefined?o.x:o.lastX),dy=o.y-(o.lastY===undefined?o.y:o.lastY);o.moving=Math.hypot(dx,dy)>.0001;if(o.moving){var heading=Math.atan2(dy,dx);o.heading=turnAngle(o.heading===undefined?heading:o.heading,heading,dt*5);o.walk=(o.walk||0)+Math.hypot(dx,dy)*9;}o.lastX=o.x;o.lastY=o.y;if(o.aimTarget&&o.aimTarget.hp>0){var target=o.aimTarget;o.aim=turnAngle(o.aim===undefined?0:o.aim,Math.atan2(target.y-o.y,target.x-o.x),dt*7);}else if(o.moving)o.aim=turnAngle(o.aim===undefined?o.heading:o.aim,o.heading,dt*4);});}

