Game.confirmMove=function(){if(!movePreview224||moving!==movePreview224.id)return;var msg=E.move(moving,movePreview224.x,movePreview224.y);if(msg){toast(msg);updateMoveControls224();return;}moving=null;movePreview224=null;selected=null;updateMoveControls224();hud();};
document.addEventListener('visibilitychange',function(){if(document.hidden)pause();else{E.sync();hud();}});root.addEventListener('pagehide',function(){E.save();});
function loop(n){requestAnimationFrame(loop);if(document.hidden){last=n;return;}if(n-last<32)return;var dt=Math.min(.08,(n-last)/1000);last=n;try{musicTick218();if(screen==='defense'&&!paused&&!E.defense.result){E.tickDefense(dt);drawNeeded=true;if(E.defense.result)defenseResult();}if(screen==='raid'&&!paused&&E.raid.phase==='battle'){E.tick(dt);drawNeeded=true;if(E.raid.result)result();}if(++frame%30===0){var jobs=E.d.buildings.filter(function(b){return b.until;}).length;E.sync();if(jobs>E.d.buildings.filter(function(b){return b.until;}).length)sound(780,.18);hud();updateTraining();}if(screen==='raid'&&E.raid&&E.raid.phase==='spectator'&&E.raid.liveMode!=='preview')drawNeeded=true;if(screen==='home'&&frame%3===0&&E.builderBusy()>0)drawNeeded=true;if(drawNeeded&&modal.style.display!=='flex'){draw();drawNeeded=false;}}catch(e){console.error('Nova frame error',e);paused=true;$('boot').style.display='block';$('bootmessage').textContent=tr('โหลดสนามไม่สำเร็จ กดลองเปิดใหม่ ข้อมูลฐานที่บันทึกไว้ยังอยู่');}}
home();$('boot').style.display='none';if(!localStorage.getItem('novaRTSIntro')){root.Game.help();try{localStorage.setItem('novaRTSIntro','1');}catch(e){}}requestAnimationFrame(loop);

var resumeCrystal=false,crystalRecoveryTimer=null;
function recoverCrystal(){
 if(warBusy)return;if(infrastructureAfterPublish&&!E.d.pendingWar){Game.warPublish(false);return;}if(!(E.d.pendingCrystal||E.d.pendingWar))return;
 if(E.d.pendingCrystal)Game.retryCrystal();else Game.retryOnline();
}
var warEventSimple=warEvent;
warEvent=function(event,message){
 if(message.request_id&&message.request_id!==warActive)return;
 var active=lastWarRequest&&lastWarRequest.action;
 if(event==='war_error'&&(E.d.pendingCrystal||E.d.pendingWar||resumeCrystal||infrastructureAfterPublish)){
  clearTimeout(warTimer);warBusy=false;warActive=null;
  var reason=String(message.message||'');
  if(/ผลึกไม่พอ|ระดับสูงสุด|ไม่พบอาคาร|สร้างและส่งผัง|ระดับกองกำลัง|กำลังอัปเกรด/.test(reason)&&active!=='cancel'){
   var p=E.d.pendingCrystal||E.d.pendingWar&&E.d.pendingWar.payload;
   toast(/ผลึกไม่พอ/.test(reason)?tr('ผลึกไม่พอ'):reason);
   if(p){warRequest('cancel',{request_id:p.request_id});return;}
  }
  toast(tr('เชื่อมต่อไม่ได้ กำลังลองใหม่อัตโนมัติ'));
  clearTimeout(crystalRecoveryTimer);crystalRecoveryTimer=setTimeout(recoverCrystal,15000);return;
 }
 if(event==='war'&&message.action==='status'&&(resumeCrystal||E.d.pendingCrystal||E.d.pendingWar)){
  clearTimeout(warTimer);warBusy=false;warActive=null;resumeCrystal=false;
  warState=message.data;syncCrystal(warState);
  if(!warState||!warState.owner){toast(tr('กรุณาเข้าสู่ระบบบัญชีเดิม'));return;}
  recoverCrystal();return;
 }
 if(event==='war'&&message.action==='cancel'&&(E.d.pendingCrystal||E.d.pendingWar)){
  clearTimeout(warTimer);warBusy=false;warActive=null;warState=message.data;syncCrystal(warState);
  var receipt=warState.receipt,p=E.d.pendingWar;
  finishCrystal(receipt);
  if(p&&receipt&&receipt.id===p.payload.request_id){delete E.d.pendingWar;E.save();}
  close();hud();return;
 }
 warEventSimple(event,message);
};
setTimeout(recoverCrystal,1500);
root.addEventListener('online',recoverCrystal);

Game.exchangeBackMenu=Game.sellResource=function(){toast(tr('ยกเลิกการแลกทรัพยากรเป็นเพชรแล้ว'));};


var resourcePolling=false;
var warRequestEconomy=warRequest;
warRequest=function(action,payload){
 if(warBusy)return;
 payload=Object.assign({},payload||{});
 if(action.indexOf('test_')!==0&&!payload.transport){
  E.sync();var ack=E.d.raidDeltas||{gold_delta:0,power_delta:0};
  E.d.resourceSeq=(E.d.resourceSeq||0)+1;
  payload.resourceSnapshot={owner:E.d.onlineCrystal&&E.d.onlineCrystal.owner,seq:E.d.resourceSeq,gold:Math.floor(E.d.gold),power:Math.floor(E.d.power),gold_delta:ack.gold_delta,power_delta:ack.power_delta,gold_cap:E.resourceCapacity(),power_cap:E.resourceCapacity('power'),gold_rate:Math.round(E.d.buildings.filter(function(b){return b.type==='mine'&&active(b);}).reduce(function(n,b){return n+2160*b.lv;},0)),power_rate:Math.round(E.d.buildings.filter(function(b){return b.type==='reactor'&&active(b);}).reduce(function(n,b){return n+2160*b.lv;},0))};
  if(!E.save()){toast(tr('บันทึกไม่ได้ กรุณาตรวจพื้นที่ว่าง'));return;}
 }
 warRequestEconomy(action,payload);
};
var warEventEconomy=warEvent;
warEvent=function(event,message){
 if(message.request_id&&message.request_id!==warActive)return;
 if(resourcePolling){resourcePolling=false;
  if(event==='war'&&message.action==='status'){clearTimeout(warTimer);warBusy=false;warActive=null;warState=message.data;syncCrystal(warState);return;}
  if(event==='war_error'||event==='war_login'){clearTimeout(warTimer);warBusy=false;warActive=null;return;}
 }
 warEventEconomy(event,message);
};
function pollResources(){
 if(lastEconomyReply&&Date.now()-lastEconomyReply<15000){setTimeout(pollResources,30000);return;}
 if(!document.hidden&&screen==='home'&&E.d.onlineCrystal&&!liveRoom&&!warBusy&&!E.d.pendingCrystal&&!E.d.pendingWar&&!E.d.pendingTest){resourcePolling=true;warRequest('status');}
 setTimeout(pollResources,30000);
}
setTimeout(pollResources,3000);


var warBrowseIntent=false;
Game.findWar=function(){warBrowseIntent=true;Game.warTargets();};
var warEventBrowse=warEvent;
warEvent=function(event,message){
 if(message.request_id&&message.request_id!==warActive)return;
 if(event==='war'&&message.data&&((message.action==='targets'&&!message.data.enrolled)||(warBrowseIntent&&['status','enroll','publish'].includes(message.action)))){
  clearTimeout(warTimer);warBusy=false;warActive=null;warState=message.data;
  if(warState.enrolled){syncCrystal(warState);Game.warTargets();}else{warBrowseIntent=true;Game.warPublish(true);}return;
 }
 if(event==='war'&&message.action==='targets'&&message.data&&message.data.enrolled){
  warBrowseIntent=false;
  if(!message.data.targets.length&&lastWarRequest&&lastWarRequest.payload.after){clearTimeout(warTimer);warBusy=false;warActive=null;Game.warTargets();return;}
 }
 warEventBrowse(event,message);
};

