var hudLive=hud;hud=function(){hudLive();var r=E.raid;if(screen!=='raid'||!r||!r.liveMode)return;$('mode').textContent=r.liveMode==='preview'?tr('สำรวจฐาน • ')+r.name:r.liveMode==='defender'?tr('🚨 ฐานกำลังถูกโจมตี'):tr('⚔ กำลังบุก • ')+r.name;if(r.liveMode==='preview'){$('clock').textContent=tr('ฐานผู้เล่น');setHTML219($('deploy'),'<button class="green" '+(liveTarget&&liveTarget.can_attack===false?'disabled':'')+tr(' onclick="Game.attackSelected()">โจมตี</button><button onclick="Game.nextTarget()">ค้นหาต่อ</button><button onclick="Game.home()">กลับฐาน</button>'));$('instruction').textContent=tr('ลากดูฐาน • ซูมได้ • เลือกโจมตีหรือค้นหาต่อ');}else if(r.liveMode==='defender'){setHTML219($('deploy'),'');$('instruction').textContent=tr('🚨 ชมการป้องกันฐานสด');}else $('instruction').textContent=tr('แตะขอบสีฟ้าเพื่อวางทหาร • การรบกำลังส่งให้อีกฝ่าย');};
