var pauseLive=pause;pause=function(){if(E.raid&&E.raid.liveMode){if(E.raid.liveMode==='attacker'){Game.retreat();}else if(E.raid.liveMode==='preview')Game.home();return;}pauseLive();};
Game.pause=pause;root.pauseGame=pause;var retreatLive=Game.retreat;Game.retreat=function(){if(E.raid&&E.raid.liveMode==='preview'){Game.home();return;}if(E.raid&&E.raid.liveMode==='defender')return;retreatLive();};
var homeLive=Game.home;Game.home=function(){if(liveRoom&&!liveRoom.finished)return;liveTarget=null;liveRoom=null;homeLive();};
function acceptLive(b){if(!b)return;if((E.d.liveReceipts||[]).includes(b.id))return;var changed=!liveRoom||liveRoom.id!==b.id;liveRoom=b;liveSeq=Math.max(liveSeq,b.seq||0);E.d.liveBattle={id:b.id,role:b.role,army:b.roster};
 if(changed||!E.raid||!E.raid.liveMode||E.raid.liveMode==='preview'){liveScene(b.target,b.role);E.raid.army=b.roster.slice();liveUnpack(b.frame);E.raid.time=Math.min(E.raid.time,b.remaining||180);if(b.role==='attacker'){E.raid.phase='battle';delete E.d.pendingLiveStart;}liveAlarm(b.role==='attacker');liveAlarmAt=Date.now();}
 if(b.role==='defender'){liveUnpack(b.frame);E.raid.phase='spectator';}
 if(b.finished){var r=b.result;if(b.role==='attacker'){var remaining=r.army||[];remaining.forEach(function(n,i){E.d.army[i]+=n;});}E.d.liveReceipts=(E.d.liveReceipts||[]).concat(b.id).slice(-500);delete E.d.liveBattle;delete E.d.pendingLiveStart;E.save();if(E.raid)E.raid.phase='result';open('<h2>'+(b.role==='attacker'?tr('ผลการโจมตี'):tr('ผลการป้องกันฐาน'))+tr('</h2><p>ทำลาย ')+r.destruction+tr('%<br>ผลึก ')+r.loot+tr(' • ทอง ')+r.loot_gold+tr(' • พลังงาน ')+r.loot_power+tr('</p><button class="wide green" onclick="Game.home()">กลับฐาน</button>'));liveSending=false;}else{E.save();hud();}
}
var warEventLive=warEvent;warEvent=function(event,message){if(message.request_id&&message.request_id!==warActive)return;var request=lastWarRequest&&lastWarRequest.payload;if(request&&request.live){clearTimeout(warTimer);warBusy=false;warActive=null;liveSending=false;if(event==='war'){var d=message.data;if(d.online){warState=d.online;syncCrystal(d.online);}if(d.live==='peek'&&d.target){liveTarget=d.target;if(E.raid&&E.raid.liveMode==='preview')liveScene(d.target,'preview');}if(d.battle)acceptLive(d.battle);if(d.live==='shield'&&d.receipt&&E.d.pendingShield&&d.receipt.id===E.d.pendingShield.request_id){delete E.d.pendingShield;E.save();toast(tr('เปิดโล่ป้องกันแล้ว'));Game.shieldShop();}return;}if(event==='war_error'){var reason=message.message||tr('เชื่อมต่อไม่ได้');if(/โล่ป้องกัน|กำลังอยู่ในการรบ|กองทัพไม่พร้อม|กองทัพไม่ถูกต้อง|เป้าหมายไม่ถูกต้อง|ไม่พบฐานผู้เล่น/.test(reason)&&E.d.pendingLiveStart){E.d.pendingLiveStart.army.forEach(function(n,i){E.d.army[i]+=n;});delete E.d.pendingLiveStart;E.save();}if(/ซื้อโล่ไม่ได้|เพชรไม่พอ/.test(reason)&&E.d.pendingShield){E.d.gems+=E.d.pendingShield.cost;delete E.d.pendingShield;E.save();}toast(reason);return;} if(event==='war_login'){var loginMessage=Object.assign({},message);delete loginMessage.request_id;warEventLive(event,loginMessage);return;} }warEventLive(event,message);};
Game.shieldShop=function(){open(tr('<h2>ร้านค้าโล่ป้องกัน</h2><p>โล่ป้องกันการบุก • หากคุณเริ่มโจมตี โล่จะสิ้นสุด</p>')+[[1,30],[6,100],[24,250]].map(function(a){return '<button class="wide" onclick="Game.buyShield('+a[0]+','+a[1]+tr(')">โล่ ')+a[0]+tr(' ชั่วโมง • ')+a[1]+' 💎</button>';}).join('')+tr('<button class="wide" onclick="Game.close()">กลับ</button>'));};
Game.buyShield=function(hours,cost){if(!E.d.onlineCrystal){Game.findWar();return;}if(warBusy)return;if(!E.d.pendingShield){if(E.d.gems<cost){toast(tr('เพชรไม่พอ'));return;}E.d.gems-=cost;E.d.pendingShield={hours:hours,cost:cost,request_id:nonce160()};if(!E.save()){E.d.gems+=cost;delete E.d.pendingShield;return;}}liveSend('shield',E.d.pendingShield);};
